"""Independent reference FWI implementation following the documented definitions.

State semantics (paper.md / cffdrs fireSeason with overwintering):
- season_mask marks active fire-season dates; dormant dates are part of the history.
- DC: last active-season DC value is carried through dormancy; winter
  precipitation P_w is the accumulation over the DORMANT interval between
  active intervals. At the first active date of each interval the daily
  recurrence starts from the overwintered state.
- DMC/FFMC are shut down to NaN outside active dates.
"""
import numpy as np

DC_START, DMC_START, FFMC_START = 15.0, 6.0, 85.0
A, B, MIN_DC = 0.75, 0.75, 15.0

DAY_LENGTHS = np.array(
    [
        [11.5, 10.5, 9.2, 7.9, 6.8, 6.2, 6.5, 7.4, 8.7, 10, 11.2, 11.8],
        [10.1, 9.6, 9.1, 8.5, 8.1, 7.8, 7.9, 8.3, 8.9, 9.4, 9.9, 10.2],
        12 * [9],
        [7.9, 8.4, 8.9, 9.5, 9.9, 10.2, 10.1, 9.7, 9.1, 8.6, 8.1, 7.8],
        [6.5, 7.5, 9, 12.8, 13.9, 13.9, 12.4, 10.9, 9.4, 8, 7, 6],
    ]
)
DAY_LENGTH_FACTORS = np.array(
    [
        [6.4, 5.0, 2.4, 0.4, -1.6, -1.6, -1.6, -1.6, -1.6, 0.9, 3.8, 5.8],
        12 * [1.39],
        [-1.6, -1.6, -1.6, 0.9, 3.8, 5.8, 6.4, 5.0, 2.4, 0.4, -1.6, -1.6],
    ]
)


def day_length(lat, mth):
    if -30 > lat >= -90:
        dl = DAY_LENGTHS[0]
    elif -15 > lat >= -30:
        dl = DAY_LENGTHS[1]
    elif 15 > lat >= -15:
        return 9
    elif 30 > lat >= 15:
        dl = DAY_LENGTHS[3]
    elif 90 >= lat >= 30:
        dl = DAY_LENGTHS[4]
    else:
        raise ValueError
    return dl[mth - 1]


def day_length_factor(lat, mth):
    if -15 > lat >= -90:
        dlf = DAY_LENGTH_FACTORS[0]
    elif 15 > lat >= -15:
        return 1.39
    elif 90 >= lat >= 15:
        dlf = DAY_LENGTH_FACTORS[2]
    else:
        raise ValueError
    return dlf[mth - 1]


def ffmc_step(t, p, w, h, ffmc0):
    mo = (147.2 * (101.0 - ffmc0)) / (59.5 + ffmc0)
    if p > 0.5:
        rf = p - 0.5
        if mo > 150.0:
            mo = (mo + 42.5 * rf * np.exp(-100.0 / (251.0 - mo)) * (1.0 - np.exp(-6.93 / rf))) + (0.0015 * (mo - 150.0) ** 2) * np.sqrt(rf)
        elif mo <= 150.0:
            mo = mo + 42.5 * rf * np.exp(-100.0 / (251.0 - mo)) * (1.0 - np.exp(-6.93 / rf))
        if mo > 250.0:
            mo = 250.0
    ed = 0.942 * (h ** 0.679) + (11.0 * np.exp((h - 100.0) / 10.0)) + 0.18 * (21.1 - t) * (1.0 - 1.0 / np.exp(0.1150 * h))
    if mo < ed:
        ew = 0.618 * (h ** 0.753) + (10.0 * np.exp((h - 100.0) / 10.0)) + 0.18 * (21.1 - t) * (1.0 - 1.0 / np.exp(0.115 * h))
        if mo < ew:
            kl = 0.424 * (1.0 - ((100.0 - h) / 100.0) ** 1.7) + (0.0694 * np.sqrt(w)) * (1.0 - ((100.0 - h) / 100.0) ** 8)
            kw = kl * (0.581 * np.exp(0.0365 * t))
            m = ew - (ew - mo) / 10.0 ** kw
        elif mo > ew:
            m = mo
    elif mo == ed:
        m = mo
    else:
        kl = 0.424 * (1.0 - (h / 100.0) ** 1.7) + (0.0694 * np.sqrt(w)) * (1.0 - (h / 100.0) ** 8)
        kw = kl * (0.581 * np.exp(0.0365 * t))
        m = ed + (mo - ed) / 10.0 ** kw
    ffmc = (59.5 * (250.0 - m)) / (147.2 + m)
    return float(min(101.0, max(0.0, ffmc)))


def dmc_step(t, p, h, mth, lat, dmc0):
    if np.isnan(dmc0):
        return np.nan
    dl = day_length(lat, mth)
    rk = 0.0 if t < -1.1 else 1.894 * (t + 1.1) * (100.0 - h) * dl * 0.0001
    if p > 1.5:
        rw = 0.92 * p - 1.27
        wmi = 20.0 + 280.0 / np.exp(0.023 * dmc0)
        if dmc0 <= 33.0:
            b = 100.0 / (0.5 + 0.3 * dmc0)
        elif dmc0 <= 65.0:
            b = 14.0 - 1.3 * np.log(dmc0)
        else:
            b = 6.2 * np.log(dmc0) - 17.2
        wmr = wmi + (1000 * rw) / (48.77 + b * rw)
        pr_ = 43.43 * (5.6348 - np.log(wmr - 20.0))
    else:
        pr_ = dmc0
    pr_ = max(pr_, 0.0)
    return max(pr_ + rk, 0.0)


def dc_step(t, p, mth, lat, dc0):
    fl = day_length_factor(lat, mth)
    t = max(t, -2.8)
    pe = max((0.36 * (t + 2.8) + fl) / 2.0, 0.0)
    if p > 2.8:
        rw = 0.83 * p - 1.27
        smi = 800.0 * np.exp(-dc0 / 400.0)
        dr = dc0 - 400.0 * np.log(1.0 + ((3.937 * rw) / smi))
        if dr > 0.0:
            dc = dr + pe
        elif np.isnan(dc0):
            dc = np.nan
        else:
            dc = pe
    else:
        dc = dc0 + pe
    return dc


def overwinter(DCf, wpr):
    if np.isnan(DCf) or np.isnan(wpr):
        return np.nan
    Qf = 800 * np.exp(-DCf / 400)
    Qs = A * Qf + B * (3.94 * wpr)
    return max(400 * np.log(800 / Qs), MIN_DC)


def fwi_calc(tas, pr, rh, ws, months, lat, mask, dc0, dmc0, ffmc0):
    """tas/pr/rh/ws: (S, T). mask: (S, T) bool. dc0/dmc0/ffmc0: (S,) or scalar."""
    S, T = tas.shape
    lat = np.atleast_1d(np.asarray(lat, dtype=float))
    dc0 = np.full(S, np.nan) if dc0 is None else np.broadcast_to(np.asarray(dc0, dtype=float), (S,))
    dmc0 = np.full(S, np.nan) if dmc0 is None else np.broadcast_to(np.asarray(dmc0, dtype=float), (S,))
    ffmc0 = np.full(S, np.nan) if ffmc0 is None else np.broadcast_to(np.asarray(ffmc0, dtype=float), (S,))

    prev_dc = dc0.copy()
    last_dc = np.full(S, np.nan)
    wpr = np.zeros(S)
    prev_dmc = dmc0.copy()
    prev_ffmc = ffmc0.copy()

    out = {k: np.full((S, T), np.nan) for k in ("DC", "DMC", "FFMC", "ISI", "BUI", "FWI")}

    def isi(ffmc, w):
        mo = 147.2 * (101.0 - ffmc) / (59.5 + ffmc)
        ff = 19.1152 * np.exp(mo * -0.1386) * (1.0 + (mo ** 5.31) / 49300000.0)
        return ff * np.exp(0.05039 * w)

    def bui(dmc, dc):
        if np.isnan(dmc) or np.isnan(dc):
            return np.nan
        if dmc <= 0.4 * dc:
            v = (0.8 * dc * dmc) / (dmc + 0.4 * dc)
        else:
            v = dmc - (1.0 - 0.8 * dc / (dmc + 0.4 * dc)) * (0.92 + (0.0114 * dmc) ** 1.7)
        return max(v, 0.0)

    def fwi(v, b):
        if np.isnan(v) or np.isnan(b):
            return np.nan
        if b <= 80.0:
            f = 0.1 * v * (0.626 * b ** 0.809 + 2.0)
        else:
            f = 0.1 * v * (1000.0 / (25.0 + 108.64 / np.exp(0.023 * b)))
        if f > 1:
            f = np.exp(2.72 * (0.434 * np.log(f)) ** 0.647)
        return f

    for it in range(T):
        active = mask[:, it]
        for s in range(S):
            if not active[s]:
                if it > 0:
                    if mask[s, it - 1]:
                        last_dc[s] = prev_dc[s]  # shut down: record end-of-season DC
                        wpr[s] = 0.0
                # dormant: accumulate precipitation only (part of history)
                wpr[s] += pr[s, it]
                continue
            # active
            if it == 0 or not mask[s, it - 1]:
                # start up
                if np.isnan(last_dc[s]):
                    dc_state = DC_START
                else:
                    dc_state = overwinter(last_dc[s], wpr[s])
                    wpr[s] = 0.0
                last_dc[s] = np.nan
                dmc_state = DMC_START
                ffmc_state = FFMC_START
            else:
                dc_state = prev_dc[s]
                dmc_state = prev_dmc[s]
                ffmc_state = prev_ffmc[s]

            dc_new = dc_step(tas[s, it], pr[s, it], months[s, it], lat[s], dc_state)
            dmc_new = dmc_step(tas[s, it], pr[s, it], rh[s, it], months[s, it], lat[s], dmc_state)
            ffmc_new = ffmc_step(tas[s, it], pr[s, it], ws[s, it], rh[s, it], ffmc_state)

            out["DC"][s, it] = dc_new
            out["DMC"][s, it] = dmc_new
            out["FFMC"][s, it] = ffmc_new
            out["ISI"][s, it] = isi(ffmc_new, ws[s, it])
            out["BUI"][s, it] = bui(dmc_new, dc_new)
            out["FWI"][s, it] = fwi(out["ISI"][s, it], out["BUI"][s, it])

            prev_dc[s] = dc_new
            prev_dmc[s] = dmc_new
            prev_ffmc[s] = ffmc_new
    return out
